#include "LocalOccurrences.h"
#include "LocalReference.h"
#include <QMap>
#include <QSet>
#include <QUuid>
#include <stdexcept>
namespace {
QJsonObject row(const QJsonObject& a,const QString& id){for(const auto& v:a["occurrences"].toArray())if(v.toObject()["id"]==id)return v.toObject();throw std::invalid_argument("Component occurrence is unavailable");}
QString owner(const QJsonObject& a,const EvaluatedBody& b){return a["objectOwners"].toObject()["bodies"].toObject().value(b.bodyId).toString(b.ownerId);}
QString label(const QJsonObject& a,const QString& id){auto r=row(a,id);QString name;for(const auto& v:a["components"].toArray())if(v.toObject()["id"]==r["definitionId"])name=v.toObject()["name"].toString();int index=0;for(const auto& v:a["occurrences"].toArray()){if(v.toObject()["definitionId"]==r["definitionId"])++index;if(v.toObject()["id"]==id)break;}return name+QString(" [%1]").arg(index);}
}
QString LocalOccurrences::parentOccurrenceId(const QJsonObject& a,const QString& id){const auto r=row(a,id);if(r.contains("parentOccurrenceId"))return r["parentOccurrenceId"].toString();if(r["parentId"]==a["documentId"])return {};QString parent;for(const auto& v:a["occurrences"].toArray()){const auto p=v.toObject();if(p["definitionId"]==r["parentId"]&&p["placement"]=="identity"&&!p.contains("parentOccurrenceId")){if(!parent.isEmpty())throw std::invalid_argument("Legacy occurrence parent is ambiguous");parent=p["id"].toString();}}if(parent.isEmpty())throw std::invalid_argument("Occurrence parent is unavailable");return parent;}
gp_Trsf LocalOccurrences::worldTransform(const QJsonObject& a,const QString& id){QString current=id;QSet<QString> visited;gp_Trsf result;while(!current.isEmpty()){if(visited.contains(current))throw std::invalid_argument("Occurrence hierarchy is cyclic");visited.insert(current);const auto r=row(a,current);gp_Trsf local;if(r["placement"]!="identity")local=LocalReference::transform(r["placement"].toObject());result=local*result;current=parentOccurrenceId(a,current);}return result;}
QJsonArray LocalOccurrences::worldPose(const QJsonObject& a,const QString& id){const auto t=worldTransform(a,id);QJsonArray p;for(int r=1;r<=3;++r)for(int c=1;c<=4;++c)p.append(t.Value(r,c));return p;}
QString LocalOccurrences::validate(const QJsonObject& a){try{QSet<QString> definitions,ids,canonical;for(const auto& v:a["components"].toArray())definitions.insert(v.toObject()["id"].toString());for(const auto& v:a["occurrences"].toArray()){const auto r=v.toObject();const auto id=r["id"].toString(),def=r["definitionId"].toString();QSet<QString> keys{"id","definitionId","parentId","placement","parentOccurrenceId"};for(auto it=r.begin();it!=r.end();++it)if(!keys.contains(it.key()))throw std::invalid_argument("Unknown occurrence field");if(QUuid(id).isNull()||ids.contains(id)||!definitions.contains(def)||!r.contains("placement"))throw std::invalid_argument("Invalid local occurrence identity");ids.insert(id);if(r["placement"]=="identity"&&!r.contains("parentOccurrenceId")){if(canonical.contains(def))throw std::invalid_argument("Duplicate legacy identity occurrence");canonical.insert(def);}else LocalReference::transform(r["placement"].toObject());if(r.contains("parentOccurrenceId")&&QUuid(r["parentOccurrenceId"].toString()).isNull())throw std::invalid_argument("Explicit parent occurrence requires a UUID");}
if(canonical!=definitions)throw std::invalid_argument("Each definition requires its original identity occurrence");for(const auto& v:a["occurrences"].toArray()){const auto r=v.toObject();const auto parent=parentOccurrenceId(a,r["id"].toString());if(parent.isEmpty()){if(r["parentId"]!=a["documentId"])throw std::invalid_argument("Root occurrence needs root owner");}else if(row(a,parent)["definitionId"]!=r["parentId"])throw std::invalid_argument("Occurrence parent and definition owner disagree");worldTransform(a,r["id"].toString());}return {};}catch(const std::exception& e){return QString::fromUtf8(e.what());}}
std::vector<EvaluatedBody> LocalOccurrences::worldBodies(const QJsonObject& a,const EvaluatedDocument& d){std::vector<EvaluatedBody> output;for(const auto& b:d.bodies){bool found=false;for(const auto& v:a["occurrences"].toArray()){const auto r=v.toObject();if(r["definitionId"].toString()!=owner(a,b))continue;const auto transform=worldTransform(a,r["id"].toString());auto placed=transform.Form()==gp_Identity?b:LocalReference::placed(b,transform);placed.occurrenceId=r["id"].toString();placed.definitionId=r["definitionId"].toString();output.push_back(std::move(placed));found=true;}if(!found)output.push_back(b);}return output;}
QJsonObject LocalOccurrences::inspect(const QJsonObject& a,const EvaluatedDocument& d){QJsonArray rows;const auto placed=worldBodies(a,d);for(const auto& v:a["occurrences"].toArray()){auto r=v.toObject();const auto id=r["id"].toString();QJsonArray bodies;for(const auto& b:placed)if(b.occurrenceId==id)bodies.append(QJsonObject{{"bodyId",b.bodyId},{"boundsMm",b.summary["boundsMm"]}});QStringList path;QString cursor=id;while(!cursor.isEmpty()){path.prepend(label(a,cursor));cursor=parentOccurrenceId(a,cursor);}r["occurrenceId"]=id;r["worldPose"]=worldPose(a,id);r["path"]=path.join(" / ");r["bodies"]=bodies;rows.append(r);}return {{"joints",QJsonArray{}},{"occurrences",rows},{"islands",QJsonArray{}}};}
